namespace StarlightSyndicateDemo;
public sealed partial class DemoWorld
{
 public static int[] HackNeighborsN(int i){int x=i%7,y=i/7;var list=new List<int>();foreach(var (dx,dy) in new[]{(-1,0),(1,0),(0,-1),(0,1),(y%2==0?-1:1,-1),(y%2==0?-1:1,1)}){int a=x+dx,b=y+dy;if(a>=0&&a<7&&b>=0&&b<7)list.Add(b*7+a);}return list.Distinct().ToArray();}
 public void ConfigureHackN(SpaceTarget t,UtilityHack h){if(ActiveEncounterF?.ProfileN==null)return;h.HexN=true;var run=EnsureExplorationGraphL(ActiveEncounterF);int level=ActiveEncounterF.ProfileN.Rating;for(int i=1;i<49;i++){double roll=run.Roll();h.Nodes[i]=roll<.2?new(){Kind=new[]{"Firewall","Antivirus","Restoration","Suppressor"}[(int)(run.Roll()*4)],Hp=35+10*level,Strength=5+2*level}:roll<.3?new(){Kind="DataCache",Hp=0}:roll<.4?new(){Kind="Cache",Tool=new[]{"Repair","Rot","Shield","Vector"}[(int)(run.Roll()*4)]}:new();}int core=Enumerable.Range(28,21).OrderBy(_=>run.Roll()).First();h.Nodes[core]=new(){Kind="Core",Hp=40+15*level,Strength=6+level};}
 public static bool HackFrontierN(UtilityHack h,int index)=>HackNeighborsN(index).Any(j=>h.Nodes[j].Cleared)&&!HackNeighborsN(index).Any(j=>h.Nodes[j].Open&&!h.Nodes[j].Cleared&&h.Nodes[j].Kind is "Firewall" or "Antivirus" or "Restoration" or "Suppressor");
 public void ResolveDataCacheN(UtilityHack h,HackNode n){var run=ActiveEncounterF==null?null:EnsureExplorationGraphL(ActiveEncounterF);double roll=run?.Roll()??RollProductionE();if(roll<.35){n.Kind=roll<.18?"Restoration":"Suppressor";n.Hp=50;n.Strength=8;}else if(h.Tools.Count<h.UtilitySlots){n.Kind="Cache";h.Tools.Add(new[]{"Repair","Rot","Shield","Vector"}[(int)((run?.Roll()??RollProductionE())*4)]);n.Cleared=true;}else{n.Kind="Cache";n.Tool=new[]{"Repair","Rot","Shield","Vector"}[(int)((run?.Roll()??RollProductionE())*4)];}}
 public void HackTurnN(UtilityHack h){if(!h.HexN||h.Complete)return;h.TurnN++;if(h.RepairTurnsN>0){h.Coherence=Math.Min(h.MaxCoherence,h.Coherence+10);h.RepairTurnsN--;}
  if(h.VectorTurnsN>0){h.VectorTurnsN--;if(h.VectorNodeN>=0&&h.VectorNodeN<h.Nodes.Length){var n=h.Nodes[h.VectorNodeN];if(n.Open&&!n.Cleared){n.Hp-=20;if(n.Hp<=0){n.Cleared=true;if(n.Kind=="Core")WinHackN(h);}}}}
  foreach(var r in h.Nodes.Where(n=>n.Open&&!n.Cleared&&n.Kind=="Restoration")){var t=h.Nodes.FirstOrDefault(n=>n.Open&&!n.Cleared&&n!=r&&n.Kind is "Firewall" or "Antivirus" or "Suppressor");if(t!=null)t.Hp+=10;}
 }
 void WinHackN(UtilityHack h){var t=Targets.FirstOrDefault(t=>t.Id==h.Target);if(t==null)return;h.Complete=h.Won=true;t.Hacked=true;RecordTaskM("Hack");StopUtility(Player.Utilities[h.Slot]);if(ActiveEncounterF is {} e)EvaluateEncounterF(e);SyncEncounterF();}
 public bool UseHackToolN(UtilityHack h,int slot,int node){if(slot<0||slot>=h.Tools.Count||node<0||node>=49||h.Complete)return false;var n=h.Nodes[node];string tool=h.Tools[slot];if(tool is "Rot" or "Vector"&&(!n.Open||n.Cleared||n.Kind is "Empty" or "Cache" or "DataCache"))return false;if(tool=="Repair"&&h.RepairTurnsN>0||tool=="Vector"&&h.VectorTurnsN>0)return false;
  h.Tools.RemoveAt(slot);switch(tool){case "Repair":h.RepairTurnsN=3;break;case "Shield":h.ShieldTurnsN=2;break;case "Rot":n.Hp=Math.Max(1,(int)Math.Ceiling(n.Hp*.5));break;case "Vector":h.VectorNodeN=node;h.VectorTurnsN=3;break;default:return false;}return true;}
}
